def mul(a,b):return [[sum(a[i][k]*b[k][j] for k in range(4)) for j in range(4)] for i in range(4)]
def inv(a):
 r=[[a[j][i] for j in range(3)]+[0] for i in range(3)]+[[0,0,0,1]]
 for i in range(3):r[i][3]=-sum(r[i][k]*a[k][3] for k in range(3))
 return r
